'use strict';

const listEl = document.getElementById('list');
const emptyEl = document.getElementById('empty');
const summaryEl = document.getElementById('summary');
const formEl = document.getElementById('composer');
const inputEl = document.getElementById('new-todo');
const clearDoneEl = document.getElementById('clear-done');
const filterEls = Array.from(document.querySelectorAll('.filters__btn'));

let todos = [];
let filter = 'all';
let editingId = null;

/* ------------------------------- network -------------------------------- */

async function api(method, url, body) {
  const res = await fetch(url, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.error || `request failed (${res.status})`);
  }
  return res.json();
}

async function refresh() {
  const data = await api('GET', '/api/todos');
  todos = data.todos;
  render();
}

/* -------------------------------- render -------------------------------- */

function visible() {
  if (filter === 'active') return todos.filter((t) => !t.done);
  if (filter === 'done') return todos.filter((t) => t.done);
  return todos;
}

function render() {
  const items = visible();
  listEl.replaceChildren();

  for (const todo of items) {
    listEl.appendChild(renderItem(todo));
  }

  const remaining = todos.filter((t) => !t.done).length;
  const done = todos.length - remaining;
  summaryEl.textContent = todos.length
    ? `${remaining} active · ${done} done`
    : 'No tasks yet';
  emptyEl.hidden = items.length > 0;
  emptyEl.textContent =
    todos.length === 0
      ? 'Nothing here yet. Add your first task above.'
      : filter === 'active'
        ? 'No active tasks. Nice work.'
        : 'No completed tasks yet.';
  clearDoneEl.hidden = done === 0;
}

function renderItem(todo) {
  const li = document.createElement('li');
  li.className = 'item' + (todo.done ? ' is-done' : '');

  const check = document.createElement('input');
  check.type = 'checkbox';
  check.className = 'item__check';
  check.checked = todo.done;
  check.setAttribute('aria-label', todo.done ? 'Mark as active' : 'Mark as done');
  check.addEventListener('change', () => toggle(todo));

  li.appendChild(check);

  if (editingId === todo.id) {
    const edit = document.createElement('input');
    edit.type = 'text';
    edit.className = 'item__text-input';
    edit.value = todo.text;
    edit.maxLength = 500;

    const commit = () => {
      const value = edit.value.trim();
      editingId = null;
      if (!value || value === todo.text) return render();
      rename(todo, value);
    };
    edit.addEventListener('blur', commit);
    edit.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { e.preventDefault(); edit.blur(); }
      if (e.key === 'Escape') { editingId = null; render(); }
    });
    li.appendChild(edit);
    queueMicrotask(() => { edit.focus(); edit.select(); });
  } else {
    const span = document.createElement('span');
    span.className = 'item__text';
    span.textContent = todo.text;
    span.title = 'Double-click to edit';
    span.addEventListener('dblclick', () => { editingId = todo.id; render(); });
    li.appendChild(span);
  }

  const del = document.createElement('button');
  del.type = 'button';
  del.className = 'item__delete';
  del.textContent = '✕';
  del.setAttribute('aria-label', 'Delete task');
  del.addEventListener('click', () => remove(todo));
  li.appendChild(del);

  return li;
}

/* -------------------------------- actions ------------------------------- */

async function add(text) {
  const { todo } = await api('POST', '/api/todos', { text });
  todos.push(todo);
  render();
}

async function toggle(todo) {
  const { todo: updated } = await api('PATCH', `/api/todos/${todo.id}`, { done: !todo.done });
  Object.assign(todo, updated);
  render();
}

